// La parte variable: los correos de la semana.
// Acá hay 3 de muestra. En tu flujo real, este nodo se reemplaza por
// Gmail > Get many messages (los correos que llegaron en la semana).
return [
  { json: {
    quien: 'Martina Sosa',
    remitente: 'Martina Sosa <martina.sosa@ejemplo.com>',
    fecha: 'viernes 25/09/2026 18:05',
    consulta: 'Hola, ¿cómo están?\n\nSoy Martina Sosa, de Panadería Sosa. Este sábado lanzamos nuestra línea de tortas por encargo y necesitamos una landing page con formulario de pedidos. Ya tengo el presupuesto aprobado y quiero arrancar hoy mismo.\n\n¿Pueden llamarme hoy? Mi WhatsApp es +54 9 11 2233-4455.\n\nGracias,\nMartina'
  } },
  { json: {
    quien: 'Julián Pereyra',
    remitente: 'Julián Pereyra <julian.pereyra@ejemplo.com>',
    fecha: 'lunes 21/09/2026 15:40',
    consulta: 'Hola, buenas tardes.\n\nEstoy averiguando cuánto sale el manejo mensual de redes sociales para una ferretería. No es para ahora, estamos armando el presupuesto del año que viene.\n\nSaludos,\nJulián Pereyra'
  } },
  { json: {
    quien: 'Rodrigo Díaz',
    remitente: 'Rodrigo Díaz <rodrigo.diaz@ejemplo.com>',
    fecha: 'miércoles 23/09/2026 10:15',
    consulta: 'Hola. Tenemos una inmobiliaria y queremos hacer anuncios en Google para vender más departamentos este trimestre. Podríamos invertir unos 500 dólares por mes. ¿Cómo trabajan?\n\nRodrigo Díaz'
  } }
];

// CUPÓN CACHÉ: cada consulta lleva el MISMO manual con el MISMO señalador.
// Es exactamente lo que ya está sobre el escritorio (nodo anterior),
// así Claude lo encuentra abierto y lo cobra 10 veces más barato.
const manual = $('El manual (parte fija)').first().json.parte_fija;

const requests = $input.all().map((item, i) => ({
  // La etiqueta de cada consulta: las respuestas vuelven mezcladas.
  custom_id: 'consulta-' + (i + 1),
  params: {
    model: 'claude-sonnet-5',
    max_tokens: 1024,
    thinking: { type: 'disabled' },
    // El manual + el señalador (cache_control). 1 hora, porque el lote puede tardar.
    system: [{ type: 'text', text: manual, cache_control: { type: 'ephemeral', ttl: '1h' } }],
    // Después del señalador, lo que cambia: el correo de esta consulta.
    messages: [{
      role: 'user',
      content: 'Remitente: ' + item.json.remitente + '\nFecha: ' + item.json.fecha + '\nConsulta:\n' + item.json.consulta
    }]
  }
}));

// Todas las consultas van en UN solo paquete.
return [{ json: { paquete: { requests } } }];

// Las respuestas llegan en formato JSONL: una línea por consulta.
// Con el custom_id sabemos de quién es cada una.
const consultas = $('Las consultas de la semana').all();
const lineas = ($input.first().json.data || '').split('\n').filter(l => l.trim());

// Precios de Claude Sonnet 5 por millón de tokens (verificados el 28/09/2026).
// Sin cupones: entrada 2, salida 10.
// En lote (la mitad): entrada 1, salida 5, lectura del escritorio 0,10, guardar 1 hora 2.
let sinCupones = 0;
let conCupones = 0;

const filas = lineas.map(linea => {
  const r = JSON.parse(linea);
  const n = Number(r.custom_id.split('-')[1]) - 1;
  const mensaje = (r.result && r.result.message) || {};
  const u = mensaje.usage || {};
  const entrada = u.input_tokens || 0;
  const guardados = u.cache_creation_input_tokens || 0;
  const leidos = u.cache_read_input_tokens || 0;
  const salida = u.output_tokens || 0;

  sinCupones += ((entrada + guardados + leidos) * 2 + salida * 10) / 1e6;
  conCupones += (entrada * 1 + guardados * 2 + leidos * 0.1 + salida * 5) / 1e6;

  // La respuesta es el JSON de la Guía 1 escrito como texto: lo abrimos.
  let datos = {};
  try {
    const texto = (mensaje.content || []).map(b => b.text || '').join('');
    datos = JSON.parse(texto.replace(/```json|```/g, '').trim());
  } catch (e) {
    datos = {};
  }

  let escritorio = 'No usó el escritorio';
  if (guardados > 0) escritorio = 'Guardó el manual otra vez (sin cupón caché)';
  if (leidos > 0) escritorio = 'Leyó el manual del escritorio (cupón caché)';

  return { json: {
    consulta: consultas[n] ? consultas[n].json.quien : r.custom_id,
    servicio: datos.servicio,
    presupuesto_usd: datos.presupuesto_usd,
    prioridad: datos.prioridad,
    escritorio
  } };
});

// Lo que costó poner el manual sobre el escritorio (precio normal, guardar 1 hora = 4).
const u0 = $('Poner el manual sobre el escritorio').first().json.usage || {};
const escritorioUsd = ((u0.input_tokens || 0) * 2 + (u0.cache_creation_input_tokens || 0) * 4) / 1e6;
conCupones += escritorioUsd;

// El ticket de 100: de cada 100 que costaría sin cupones, cuánto pagamos.
const cantidad = filas.length;
const deCada100 = Math.round(conCupones / sinCupones * 100);
// Lo mismo con 600 consultas: el manual se pone sobre el escritorio una sola vez
// y ese costo se reparte entre todas.
const con600 = Math.round((escritorioUsd + (conCupones - escritorioUsd) / cantidad * 600) / (sinCupones / cantidad * 600) * 100);

filas.push({ json: {
  consulta: 'TOTAL (' + cantidad + ' consultas)',
  costo_sin_cupones_usd: Number(sinCupones.toFixed(4)),
  costo_con_cupones_usd: Number(conCupones.toFixed(4)),
  de_cada_100_pagaste: deCada100,
  con_600_consultas_pagarias: con600,
  en_palabras: 'Con ' + cantidad + ' consultas pagaste ' + deCada100 + ' de cada 100. ' +
    'Con 600 pagarías unos ' + con600 + ': poner el manual sobre el escritorio se paga una sola vez y se reparte entre todas.'
} });

return filas;
